def decode_captures(job, csv_module, zstd):
    """Independent transport + record path; returns (rows, rejected, error)."""
    rows = []
    rejected = []
    total_chunks = 0
    decoded_total = 0
    plain_total = 0
    try:
        for number, capture in enumerate(job['captures']):
            if capture['encoding'] not in ('csv', 'zstd'):
                raise Bad('encoding')
            total_chunks += len(capture['chunks'])
            if total_chunks > 1024:
                raise Bad('chunk budget')
            blob = b''.join(base64.b64decode(c.encode('ascii'), validate=True)
                            for c in capture['chunks'])
            decoded_total += len(blob)
            if decoded_total > 32 * 1024 ** 2:
                raise Bad('decoded budget')
            if capture['encoding'] == 'zstd':
                plain = zstd.ZstdDecompressor().decompress(
                    blob, max_output_size=128 * 1024 ** 2) if False else \
                    zstd.ZstdDecompressor().stream_reader(
                        __import__('io').BytesIO(blob), read_across_frames=True).read()
            else:
                plain = blob
            plain_total += len(plain)
            if plain_total > 128 * 1024 ** 2:
                raise Bad('plain budget')
            text = plain.decode('utf-8')
            reader = csv_module.reader(__import__('io').StringIO(text, newline=''),
                                       strict=True)
            header = next(reader, None)
            if header != COLS:
                raise Bad('header')
            ordinal = 0
            for values in reader:
                current = ordinal
                ordinal += 1
                if len(values) > 14 or any(len(v.encode('utf-8')) > 131072 for v in values):
                    raise Bad('field budget')
                try:
                    rows.append(parse_row(values, job, PROBES[0]))
                except Bad:
                    rejected.append([number, current])
        return rows, rejected, None
    except Bad as exc:
        return None, None, 'capture'
    except Exception:
        return None, None, 'capture'


